mapper.select:

where q.del_flag = '0'

    and exists (
        select 1 from smx_expert_crop c
        where c.crop = q.crop and c.category = #{category}
    )

 and q.crop = #{crop}


    and (q.title like concat('%', #{keyword}, '%')
         or q.content like concat('%', #{keyword}, '%')
         or q.crop like concat('%', #{keyword}, '%'))

 and q.status = #{status}
 and q.user_id = #{userId}
 and q.title like concat('%', #{title}, '%')
order by q.create_time desc
